package com.footballacademy.model;
import com.fasterxml.jackson.annotation.JsonIgnore; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="player_progressions", indexes={@Index(name="idx_progression_player", columnList="player_id"),@Index(name="idx_progression_metric", columnList="metric_name")})
public class PlayerProgression { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="player_id") @JsonIgnore private Player player; private String metricName; private Double oldValue; private Double newValue; private Double changeRate; private LocalDateTime recordedAt=LocalDateTime.now(); public boolean isImproving(){return changeRate!=null?changeRate>0:(newValue!=null&&oldValue!=null&&newValue>oldValue);} public Long getId(){return id;} public void setId(Long id){this.id=id;} public Player getPlayer(){return player;} public void setPlayer(Player player){this.player=player;} public String getMetricName(){return metricName;} public void setMetricName(String metricName){this.metricName=metricName;} public Double getOldValue(){return oldValue;} public void setOldValue(Double oldValue){this.oldValue=oldValue;} public Double getNewValue(){return newValue;} public void setNewValue(Double newValue){this.newValue=newValue;} public Double getChangeRate(){return changeRate;} public void setChangeRate(Double changeRate){this.changeRate=changeRate;} public LocalDateTime getRecordedAt(){return recordedAt;} public void setRecordedAt(LocalDateTime recordedAt){this.recordedAt=recordedAt;} }
